package Model;

import com.google.api.client.googleapis.javanet.GoogleNetHttpTransport;
import com.google.api.client.json.gson.GsonFactory;
import com.google.api.services.gmail.Gmail;
import com.google.api.services.gmail.model.Message;

import jakarta.mail.*;
import jakarta.mail.internet.*;

import javafx.beans.property.SimpleStringProperty;
import javafx.beans.property.StringProperty;

import java.io.ByteArrayOutputStream;
import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.security.GeneralSecurityException;
import java.util.Properties;

import org.apache.commons.codec.binary.Base64;

/**
 * Handles emailing functionality through Gmail.
 */
public class Email {

    /** Sender's Gmail address (only for 'From' field). */
    private static final String SENDING = "custom77429@gmail.com";

    /** Email subject. */
    private static final String SUBJECT = "FILE WATCHER UPDATE";

    /** User's email address. */
    private String myEmail;

    /** Property for GUI update. */
    private StringProperty myProperty;

    /**
     * Constructor for Email.
     * @param theEmail the recipient email.
     */
    public Email(final String theEmail) {
        myProperty = new SimpleStringProperty();
        changeEmail(theEmail);
    }

    /**
     * Updates the recipient email.
     * @param theNewEmail new email.
     */
    public void changeEmail(final String theNewEmail) {
        if (theNewEmail.isEmpty()) {
            throw new IllegalArgumentException("Email is empty!");
        }
        myEmail = theNewEmail;
        myProperty.set(myEmail);
    }

    /**
     * Sends an email with message and file.
     * @param theMessage the text body.
     * @param theFile the attachment.
     */
    public void sendEmail(final String theMessage, final File theFile) {
        try {
            MimeMessage email = createEmail(myEmail, theMessage, theFile);
            Message message = createMessageWithEmail(email);

        } catch (MessagingException | IOException e) {
            System.out.println("Error caught while sending email: " + e.getMessage());
        }
    }

    /**
     * Creates an email with body and file.
     * @param theReceivingAddress the email receiver.
     * @param theBody email body.
     * @param theFile attachment file.
     * @return MimeMessage.
     */
    private static MimeMessage createEmail(final String theReceivingAddress,
                                           final String theBody,
                                           final File theFile)
            throws MessagingException, IOException {

        Properties props = new Properties();
        Session session = Session.getDefaultInstance(props, null);

        MimeMessage email = new MimeMessage(session);
        email.setFrom(new InternetAddress(SENDING));
        email.addRecipient(Message.RecipientType.TO, new InternetAddress(theReceivingAddress));
        email.setSubject(SUBJECT);

        // Text body
        MimeBodyPart textPart = new MimeBodyPart();
        textPart.setText(theBody);

        // File attachment
        MimeBodyPart filePart = new MimeBodyPart();
        filePart.attachFile(theFile);

        // Combine parts
        Multipart multipart = new MimeMultipart();
        multipart.addBodyPart(textPart);
        multipart.addBodyPart(filePart);

        email.setContent(multipart);

        return email;
    }

    /**
     * Encodes MimeMessage into a Gmail API Message.
     * @param theMessage the email.
     * @return Gmail API Message.
     */
    private static Message createMessageWithEmail(final MimeMessage theMessage)
            throws MessagingException, IOException {

        ByteArrayOutputStream buffer = new ByteArrayOutputStream();
        theMessage.writeTo(buffer);
        byte[] bytes = buffer.toByteArray();

        String encodedEmail = Base64.encodeBase64URLSafeString(bytes);
        Message message = new Message();
        message.setRaw(encodedEmail);

        return message;
    }
}
